CREATE TABLE t3(a,b,c); WITH RECURSIVE cte(x) AS (VALUES(1) UNION SELECT x+1 FROM cte WHERE x<30) INSERT INTO t3(a,b,c) SELECT x, printf('ab%04xyz',x), x*100003 FROM cte; CREATE UNIQUE INDEX t3abc ON t3(CAST(a AS text), b, substr(c,1,3)); CREATE TABLE sfi_result(seq,val); INSERT INTO sfi_result(seq,val) SELECT 1,a FROM t3 WHERE CAST(a AS text)<='10' ORDER BY +a; INSERT INTO sfi_result(seq,val) SELECT 2,integrity_check FROM pragma_integrity_check;